S = "Hakeem Force Academy"
QS = [
(S, "Which country is known as the land of golden fibre?", ["India", "Bangladesh", "Nepal", "Myanmar"], 1,
 "Jute is called the golden fibre because of its golden colour and high value, and Bangladesh is the world's leading producer of it. So Bangladesh is called the land of golden fibre.",
 "Bangladesh was East Pakistan until 1971.", [4345]),
(S, "Sputnik 1, the first artificial satellite launched into space, was launched in which year?", ["1961", "1945", "1969", "1957"], 3,
 "The Soviet Union launched Sputnik 1 on 4 October 1957, which started the space age.",
 "The first crewed spaceflight was Vostok 1 carrying Yuri Gagarin on 12 April 1961.", [1080]),
(S, "Who was appointed as the first commander of the Muslim army in the Battle of Mu'tah?", ["Hazrat Zayd bin Haritha (RA)", "Hazrat Khalid bin Walid (RA)", "Hazrat Ali (RA)", "Hazrat Hamza (RA)"], 0,
 "The Prophet (PBUH) appointed Hazrat Zayd bin Haritha as commander, with Hazrat Jafar bin Abi Talib and Hazrat Abdullah bin Rawaha next in line. After all three were martyred, Hazrat Khalid bin Walid took command.",
 "The Battle of Mu'tah was fought in 8 AH against the Byzantine forces.", [5171]),
(S, "Who founded the All India Muslim League in 1906 at Dhaka, hosting the meeting where it was formed?", ["Nawab Salimullah Khan", "Allama Iqbal", "Sir Syed Ahmad Khan", "Liaquat Ali Khan"], 0,
 "The All India Muslim League was formed on 30 December 1906 at Dhaka at a meeting hosted by Nawab Khwaja Salimullah of Dhaka. Nawab Waqar-ul-Mulk and Nawab Mohsin-ul-Mulk were also prominent in its formation.",
 "Sir Sultan Muhammad Shah Aga Khan III was its first president.", [4843]),
(S, "What is the process of loss of water vapour from the leaves of a plant called?", ["Transpiration", "Respiration", "Photosynthesis", "Germination"], 0,
 "Plants lose water as vapour mainly through the stomata of their leaves, and this process is called transpiration. It also helps pull water up from the roots.",
 "Guard cells control the opening and closing of stomata.", [3647, 3648]),
(S, "What is the antonym of the word lethal?", ["Deadly", "Harmless", "Fatal", "Poisonous"], 1,
 "Lethal means able to cause death, so its opposite is harmless. Deadly, fatal and poisonous are synonyms or close in meaning.",
 "The word lethal comes from the Latin word letum, meaning death.", [290]),
(S, "Which word is closest in meaning to lethal?", ["Gentle", "Weak", "Deadly", "Useful"], 2,
 "Lethal means capable of causing death, which is the same as deadly.",
 "Lethal injection is a method of execution in some countries.", [3271, 3741]),
(S, "Which letter comes next in the series: a, c, d, f, ...?", ["g", "h", "i", "e"], 0,
 "The positions are 1, 3, 4, 6 and the steps alternate +2 and +1. After 6 the step is +1, giving position 7, which is g.",
 "The English alphabet has 26 letters.", [4499]),
(S, "Which comes next in the series: A3, C5, E7, G9, ?", ["H10", "J11", "I10", "I11"], 3,
 "The letters skip one each time (A, C, E, G, I) and the numbers go up by 2 (3, 5, 7, 9, 11). So the next term is I11.",
 "Letters moving by two places each step are a common pattern in verbal reasoning.", [4500]),
(S, "Which letter comes next in the series: Z, X, U, Q, ?", ["N", "M", "K", "L"], 3,
 "The positions are 26, 24, 21, 17 and the differences are 2, 3, 4, so the next difference is 5. 17 minus 5 is 12, which is L.",
 "The differences in this series increase by 1 each time.", [329]),
(S, "Which comes next in the series: z1, x3, v5, ?", ["t7", "u7", "t6", "s7"], 0,
 "The letters go backwards skipping one (z, x, v, t) and the numbers go up by 2 (1, 3, 5, 7). So the next term is t7.",
 "z is the 26th letter, x the 24th, v the 22nd and t the 20th.", [4503]),
(S, "Rearranging the letters AGREMYN gives the name of which country?", ["Armenia", "Germany", "Myanmar", "Gabon"], 1,
 "The letters A, G, R, E, M, Y, N can be arranged to spell GERMANY, using all seven letters exactly once.",
 "Berlin is the capital of Germany.", [4496]),
(S, "In which city is the National Library of Pakistan located?", ["Lahore", "Karachi", "Islamabad", "Peshawar"], 2,
 "The National Library of Pakistan is located in Islamabad on Constitution Avenue in the same complex as other national institutions.",
 "It was established in 1951 in Karachi and later moved to Islamabad.", [2189, 325]),
(S, "The Kirthar Range is regarded as the southern extension of which mountain range?", ["Sulaiman Range", "Karakoram Range", "Hindu Kush", "Salt Range"], 0,
 "The Kirthar Range runs north to south along the border of Sindh and Balochistan and is usually described as the southern extension of the Sulaiman Range.",
 "Some sources treat the Kirthar Range as a separate range; its highest point is Kutte Ji Kabar.", [265]),
(S, "Who said that the life of the Prophet (PBUH) was a reflection of the Holy Quran, saying his character was the Quran?", ["Hazrat Ayesha (RA)", "Hazrat Umar (RA)", "Hazrat Ali (RA)", "Hazrat Abu Bakr (RA)"], 0,
 "When asked about the character of the Prophet (PBUH), Hazrat Ayesha (RA) replied that his character was the Quran. This means his life was a practical reflection of the Quran.",
 "Hazrat Ayesha (RA) was the daughter of Hazrat Abu Bakr (RA) and narrated over 2000 hadiths.", [5018]),
(S, "Which is the last heavenly (divine) book?", ["Torah", "Zaboor", "Injeel", "Quran"], 3,
 "The Holy Quran was revealed to the last Prophet Muhammad (PBUH) and is the final divine book. No book will come after it.",
 "The other heavenly books are the Torah, Zaboor and Injeel.", [1152]),
(S, "Which is the largest flower in the world?", ["Sunflower", "Lotus", "Rafflesia", "Rose"], 2,
 "Rafflesia arnoldii, found in the rainforests of Indonesia, has the largest single flower, which can be about one metre across.",
 "It has no leaves, stems or roots and is a parasite on vines.", [4447]),
(S, "In which unit is latitude measured?", ["Metres", "Kilometres", "Degrees", "Hours"], 2,
 "Latitude is the angular distance north or south of the Equator, so it is measured in degrees.",
 "The Equator is 0 degrees latitude and the poles are 90 degrees north and south.", [2149, 2322]),
(S, "Change into passive voice: All his friends laughed at him.", ["He was laughed at by all his friends.", "He is laughed at by all his friends.", "He had laughed at all his friends.", "All his friends were laughed at by him."], 0,
 "The sentence is in simple past tense, so the passive uses was or were with the past participle. The object him becomes the subject he, giving He was laughed at by all his friends.",
 "Phrasal verbs such as laugh at keep their preposition in the passive voice.", [1583]),
(S, "I want a book ___ is not in the library. Fill in the blank.", ["who", "whom", "which", "whose"], 2,
 "A relative pronoun for a thing is which, so it correctly links to the book. Who and whom are used for people.",
 "That can also be used here in place of which.", [1960]),
(S, "Is x = 3y + 1 a linear equation?", ["Yes, it is linear in x and y", "No, because it has a constant", "No, because it has two variables", "No, because its degree is 2"], 0,
 "Each variable appears only with power 1 and there are no products of variables, so it is a linear equation in two variables. Its graph is a straight line.",
 "A linear equation always has degree 1.", [2448]),
(S, "What does the name Israel literally mean?", ["Servant of Allah", "Land of peace", "Gift of God", "Chosen city"], 0,
 "Israel is the title of Prophet Yaqub (AS) and means servant of Allah in the Hebrew tradition. Isra means servant and El means God.",
 "The Children of Israel are the descendants of Hazrat Yaqub (AS).", [2903]),
(S, "In which month and year did the last US troops leave Afghanistan?", ["August 2021", "December 2014", "May 2021", "February 2020"], 0,
 "The final US military flights left Kabul airport on 30 August 2021 (31 August in Kabul), ending a war of about twenty years. The Taliban had taken Kabul on 15 August 2021.",
 "The US-led invasion of Afghanistan began in October 2001.", [4053]),
]
